// Explorer-owned working memory. The caller selected this map and the rule that
// unresolved relevant views cannot be reported as completed exploration.
import { uiModelFormat } from "./application-ui-model.mjs";
const text = { type: "string" };
const strings = { type: "array", items: text };
const record = (properties) => ({
  type: "object",
  properties,
  required: Object.keys(properties),
  additionalProperties: false,
});
// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
const node = record({
  id: text,
  parentId: { type: ["string", "null"] },
  pageName: {
    type: ["string", "null"],
    description:
      "Name of the observed page model containing this view, if known.",
  },
  name: text,
  kind: text,
  entryPoint: text,
  state: {
    type: "string",
    enum: ["pending", "explored", "blocked", "out_of_scope"],
  },
  questions: {
    ...strings,
    description:
      "Remaining questions about where to find the view or what it contains. Clear answered questions on this node.",
  },
  reason: text,
});
export const explorationMapTool = {
  name: "update_exploration_map",
  description:
    "Save observed page models together with discovered views, navigation links and remaining work. Record forms, fields, controls and variants now, when observed. Page/model collections are upserted by their names; empty collections leave previous observations intact. Keep one ID for each distinct view, including the starting view. The reply shows the saved model and frontier. This performs no browser action.",
  parameters: record({
    currentViewId: {
      type: ["string", "null"],
      description:
        "ID of the explored node you are observing on the current screen. Kaijan attaches the current capture. Use null for graph updates without a current observation.",
    },
    nodes: { type: "array", items: node },
    edges: {
      type: "array",
      items: record({ from: text, action: text, to: text }),
    },
    pages: uiModelFormat.schema.properties.pages,
  }),
};

// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const explorationMapInstruction = `Start at the target in your app model. When a screenshot reveals a new task-related page, dialog, menu or state, call update_exploration_map before your next browser action. Identify the currently observed view with currentViewId and record where it leads. Reuse the same node IDs and page names for updates. If a screenshot shows a state already in the app model, choose the next pending view.
Explore pending task-related views in breadth-first order. Keep remaining structural questions on the corresponding node. Mark each view explored and clear its questions when you have seen its relevant structure. Leave functional expectations for Planner and Runner. Finish when Planner can follow the workflow through the views in the app model and no relevant views or UI questions remain. Your final status accompanies the app model you saved.`;

export function explorerOutputFormat() {
  return {
    type: "json_schema",
    name: "ui_exploration_report",
    strict: true,
    schema: record({
      report: record({
        status: { type: "string", enum: ["complete", "incomplete"] },
        reason: text,
      }),
    }),
  };
}

// Preserve separately observed structures when a later update describes only
// another form/control on the same page. Unknowns are replaced when resolved;
// ordinary observations retain their attributed values and screenshot IDs.
function mergeObserved(previous, update) {
  if (Array.isArray(update)) {
    const result = structuredClone(previous ?? []);
    const key = (value) =>
      typeof value !== "object" || value === null
        ? JSON.stringify(value)
        : JSON.stringify(
            value.name ??
              value.description ??
              (value.control !== undefined
                ? [value.control, value.destination]
                : value.label !== undefined
                  ? [value.label, value.value]
                  : value),
          );
    for (const value of update) {
      const index = result.findIndex((old) => key(old) === key(value));
      if (index < 0) result.push(structuredClone(value));
      else result[index] = mergeObserved(result[index], value);
    }
    return result;
  }
  if (update && typeof update === "object") {
    const result = structuredClone(previous ?? {});
    for (const [key, value] of Object.entries(update))
      result[key] =
        key === "observationLimits"
          ? structuredClone(value)
          : mergeObserved(result[key], value);
    return result;
  }
  return update;
}

export function createExplorationMap(initialURL) {
  const nodes = new Map([
    [
      "target",
      {
        id: "target",
        parentId: null,
        name: "Requested application view",
        kind: "page",
        entryPoint: initialURL,
        state: "pending",
        evidence: [],
        questions: [],
        reason: "Caller-selected target",
      },
    ],
  ]);
  const edges = new Map();
  const pages = new Map();
  const uiModel = () => ({ pages: [...pages.values()], unknowns: [] });
  const snapshot = () => ({
    nodes: [...nodes.values()],
    edges: [...edges.values()],
    uiModel: uiModel(),
  });
  const remaining = () => {
    const unresolved = [...nodes.values()].filter(
      (n) =>
        n.state === "pending" ||
        n.state === "blocked" ||
        (n.state !== "out_of_scope" && n.questions.length),
    );
    const missing = new Set();
    for (const n of nodes.values())
      if (n.parentId !== null && !nodes.has(n.parentId))
        missing.add(n.parentId);
    for (const e of edges.values()) {
      if (!nodes.has(e.from)) missing.add(e.from);
      if (!nodes.has(e.to)) missing.add(e.to);
    }
    return { views: unresolved, unrecordedNodeIds: [...missing] };
  };
  return {
    snapshot,
    remaining,
    uiModel,
    update(update, observationId) {
      const recorded = update.nodes.map((view) => {
        const prior = nodes.get(view.id);
        const capture =
          view.id === update.currentViewId && view.state === "explored"
            ? observationId
            : undefined;
        const earlier = prior?.evidence ?? [];
        if (
          capture &&
          prior?.pageName &&
          view.pageName &&
          prior.pageName !== view.pageName &&
          earlier.length &&
          !earlier.includes(capture)
        )
          throw Error(
            `View "${view.id}" already records "${prior.pageName}". Give the distinct view "${view.pageName}" its own ID and link it with an action.`,
          );
        const evidence = capture
          ? [...new Set([...earlier, capture])]
          : earlier;
        return {
          ...view,
          state:
            view.state === "explored" && !evidence.length
              ? "pending"
              : view.state,
          evidence,
        };
      });
      for (const view of recorded) nodes.set(view.id, structuredClone(view));
      for (const e of update.edges)
        edges.set(JSON.stringify([e.from, e.action, e.to]), structuredClone(e));
      for (const p of update.pages ?? [])
        pages.set(p.name, mergeObserved(pages.get(p.name), p));
      return {
        recorded: true,
        frontier: remaining(),
        uiModel: uiModel(),
        explored: [...nodes.values()]
          .filter((n) => n.state === "explored")
          .map((n) => n.id),
      };
    },
    toDot() {
      const colors = {
        pending: "goldenrod",
        explored: "forestgreen",
        blocked: "firebrick",
        out_of_scope: "gray",
      };
      const lines = [
        "digraph Exploration {",
        "rankdir=LR;",
        "node [shape=box];",
      ];
      for (const n of nodes.values())
        lines.push(
          `${JSON.stringify(n.id)} [label=${JSON.stringify(n.name + "\n" + n.state)}, color=${JSON.stringify(colors[n.state])}];`,
        );
      for (const n of nodes.values())
        if (
          n.parentId !== null &&
          ![...edges.values()].some(
            (e) => e.from === n.parentId && e.to === n.id,
          )
        )
          lines.push(
            `${JSON.stringify(n.parentId)} -> ${JSON.stringify(n.id)};`,
          );
      for (const e of edges.values())
        lines.push(
          `${JSON.stringify(e.from)} -> ${JSON.stringify(e.to)} [label=${JSON.stringify(e.action)}];`,
        );
      return lines.concat("}").join("\n");
    },
  };
}
